214-LANGUAGE plpgsql
215-SECURITY DEFINER
216-SET search_path = public
217-AS $$
218-DECLARE
219-  horarios TEXT[];
220-  total NUMERIC := 0;
221-  sinal NUMERIC;
222-  h TEXT;
223-  novo_id TEXT := 'rsv_mcp_' || replace(gen_random_uuid()::text, '-', '');
224-  digitos TEXT := regexp_replace(COALESCE(p_whatsapp, ''), '\D', '', 'g');
225-BEGIN
226-  SELECT array_agg(DISTINCT x ORDER BY x) INTO horarios FROM unnest(p_horarios) AS x;
227-  IF horarios IS NULL OR p_quadra_id IS NULL OR p_data IS NULL OR p_data < CURRENT_DATE
228-     OR length(trim(COALESCE(p_nome, ''))) < 2 OR length(digitos) < 10 THEN
229-    RAISE EXCEPTION 'dados_invalidos' USING ERRCODE = 'P0001';
230-  END IF;
231-  FOREACH h IN ARRAY horarios LOOP
232-    total := total + public.valor_hora_quadra(h);
233-  END LOOP;
234-  IF substr(horarios[array_length(horarios, 1)], 1, 2)::int - substr(horarios[1], 1, 2)::int
235-     <> array_length(horarios, 1) - 1 THEN
236-    RAISE EXCEPTION 'horarios_nao_consecutivos' USING ERRCODE = 'P0001';
237-  END IF;
238-  IF public.telefone_bloqueado(digitos) THEN
239-    RAISE EXCEPTION 'usuario_bloqueado' USING ERRCODE = 'P0001';
240-  END IF;
241-
242-  sinal := round(total * 0.4, 2);
243-
244-  INSERT INTO reservas (
245-    id, quadra_id, data, horarios, hora_inicio, hora_fim, nome_cliente, whatsapp_cliente,
246-    valor_total, valor_sinal, valor_pendente, status, tipo_reserva, esporte, observacoes
247-  ) VALUES (
248-    novo_id, p_quadra_id, p_data, horarios, horarios[1],
249-    lpad((substr(horarios[array_length(horarios, 1)], 1, 2)::int + 1)::text, 2, '0') || ':00',
250-    trim(p_nome), digitos, total, sinal, total - sinal, 'pendente', 'avulsa', p_esporte,
251-    'Reserva criada pelo agente (MCP), sinal a confirmar'
252-  );
253-
254-  RETURN novo_id;
255-END;
256-$$;
