 * Salva itens de galeria no cache local.
 */
function setGaleriaLocal(itens: GaleriaItem[]): void {
  if (typeof window === "undefined") return;
  try {
    localStorage.setItem(STORAGE_KEY_GALERIA, JSON.stringify(itens));
  } catch {}
}

