      /^https://wa.me/5591988887777?/
    );

    fireEvent.click(screen.getByRole("button", { name: /Fale Conosco/ }));
    expect(screen.getByText("Arena Belém")).toBeInTheDocument();
    expect(screen.getByRole("link", { name: /Abrir Conversa no WhatsApp/ }).getAttribute("href")).toMatch(
      /^https://wa.me/5591988887777?/
    );
  });
});

